// === n8n 企業級大腦：陣列批次優化與 CEO 分級授信引擎 (V3 欄位精準對齊版) ===

let autoCount = 0;
let reviewCount = 0;
let rejectCount = 0;
let processedItems = [];

// 1. 瞬間掃描 1,500 筆訂單大軍
for (let item of $input.all()) {
    let json = item.json; 

    // 基礎金額與庫存計算
    let qty = Number(json['數量']) || 0;
    let price = Number(json['單價']) || 0;
    let stock = Number(json['期末庫存']) || 0;
    let safeStock = Number(json['安全庫存']) || 0;

    json['訂單金額'] = qty * price;
    json['可用庫存'] = stock - safeStock;

    // 2. ⭐ CEO 級分級授信決策樹 (精準對齊 Excel 資料字典)
    // 🔥 關鍵修復：抓取 Excel 裡正確的「信用評等」欄位！
    let credit = json['信用評等']; 
    let orderAmount = json['訂單金額'];
    let availableStock = json['可用庫存'];

    // 如果找不到信用評等(undefined)，或是新名單，才判定為新客戶
    if (!credit || credit === '新客戶(未授信)') {
        json['決策'] = 'review';
        json['攔截原因'] = '缺乏歷史交易紀錄，需進行 KYC 與信用評級';
        reviewCount++;
    } else if (credit === 'C') {
        json['決策'] = 'reject';
        json['攔截原因'] = 'C級高風險呆帳客群，系統鎖定退單';
        rejectCount++;
    } else if (credit === 'A' && availableStock >= 0 && orderAmount < 150000) {
        // A級優良客戶享有 15萬 快速通關履約額度
        json['決策'] = 'auto';
        autoCount++;
    } else if (credit === 'B' && availableStock >= 0 && orderAmount < 30000) {
        // B級一般客戶維持 3萬 安全通關額度
        json['決策'] = 'auto';
        autoCount++;
    } else {
        // 額度超標或實體庫存不足，轉入人工例外管理
        json['決策'] = 'review';
        json['攔截原因'] = (availableStock < 0) ? '實體庫存不足，需人工調撥排產' : '訂單金額超標，需財務主管覆核';
        reviewCount++;
    }

    processedItems.push(json);
}

// 3. 把戰情統計總數全域注入
for (let json of processedItems) {
    json['總處理筆數'] = processedItems.length;
    json['直通出貨_Auto'] = autoCount;
    json['人工審核_Review'] = reviewCount;
    json['退單攔截_Reject'] = rejectCount;
    json['狀態'] = "動態授信與大腦運算完成";
}

// 4. 返回乾淨陣列給 Switch 進行物理分流
return processedItems.map(json => ({ json: json }));

// === n8n 企業級 ERP 財務結算與庫存扣減引擎 (單輸出完全體) ===
let processedItems = [];

for (let item of $input.all()) {
    let json = item.json;

    // 1. 執行實時庫存扣減
    let currentStock = Number(json['期末庫存']) || 0;
    let safeStock = Number(json['安全庫存']) || 0;
    let orderQty = Number(json['數量']) || 0;
    let newStock = currentStock - orderQty;
    json['更新後庫存水位'] = newStock;

    // 2. 財務結算：總支出(COGS)、總收入(Revenue) 與 交易毛利分析
    let unitCost = Number(json['單位成本']) || 0; 
    let unitPrice = Number(json['單價']) || 0;

    json['銷貨收入(Revenue)'] = orderQty * unitPrice;
    json['銷貨成本(COGS)'] = orderQty * unitCost; // 這就是該筆訂單的總支出
    json['交易毛利(Gross Profit)'] = json['銷貨收入(Revenue)'] - json['銷貨成本(COGS)'];

    // 計算毛利率
    if (json['銷貨收入(Revenue)'] > 0) {
        json['毛利率(Margin %)'] = ((json['交易毛利(Gross Profit)'] / json['銷貨收入(Revenue)']) * 100).toFixed(2) + '%';
    } else {
        json['毛利率(Margin %)'] = '0%';
    }

    // 3. 雙式簿記會計傳票過帳標籤
    json['借方科目(Dr.)'] = "應收帳款(AR) / 銷貨成本(COGS)";
    json['貸方科目(Cr.)'] = "銷貨收入(Rev) / 存貨(INV)";
    json['過帳狀態'] = "GL_POSTED";

    // 4. ⭐ 智能補貨標籤：為後續的畫布 Filter 節點提供完美的辨識暗號
    if (newStock < safeStock) {
        json['需要補貨'] = true;
        json['建議採購量(PR)'] = safeStock - newStock + 150; // 補足缺口並加上安全安全存量
    } else {
        json['需要補貨'] = false;
        json['建議採購量(PR)'] = 0;
    }

    processedItems.push({ json: json });
}

// 完美返回單一陣列，再也不會觸發 Return items properly 錯誤！
return processedItems;

// === n8n 報表改名引擎：人工覆核戰情表 ===

// 1. 抓取今天日期 (格式: 20260517)
const today = new Date();
const dateStr = `${today.getFullYear()}${String(today.getMonth() + 1).padStart(2, '0')}${String(today.getDate()).padStart(2, '0')}`;

// 2. 幫 XLSX 二進位檔案蓋上專屬檔名
for (let item of $input.all()) {
    if (item.binary && item.binary.data) {
        item.binary.data.fileName = `台灣精密零件_人工覆核戰情表_${dateStr}.xlsx`;
    }
}

return $input.all();

