let reportData = [];
for (let item of $input.all()) {
    let j = item.json;
    // 重組並只保留高階主管需要的關鍵欄位 (順序即為 Excel 欄位順序)
    reportData.push({
        json: {
            "訂單編號": j['訂單ID'],
            "客戶編號": j['客戶ID'],
            "信用評等": j['客戶信用評等'],
            "攔截原因": j['攔截原因'] || '需人工覆核',
            "產品代碼": j['產品代碼'],
            "訂單數量": j['數量'],
            "訂單總額(NT$)": j['訂單金額'],
            "當前可用庫存": j['可用庫存']
        }
    });
}
return reportData;

let reportData = [];
for (let item of $input.all()) {
    let j = item.json;
    reportData.push({
        json: {
            "退單編號": j['訂單ID'],
            "高風險客戶": j['客戶ID'],
            "信用評等": j['客戶信用評等'],
            "退回原因": j['攔截原因'],
            "攔截金額(NT$)": j['訂單金額'],
            "風險防禦結果": "已成功攔截出貨，避免呆帳損失"
        }
    });
}
return reportData;

// === n8n 企業級 CRM 欄位清洗引擎 (黑盒子戰情探針版) ===
let reportData = [];
let sampleKeys = [];
let sampleData = null;

for (let item of $input.all()) {
    let j = item.json;

    // 記錄第一筆資料的結構，用來診斷
    if (sampleKeys.length === 0) {
        sampleKeys = Object.keys(j);
        sampleData = j;
    }

    let isNewCustomer = false;
    if (!j['信用評等'] || j['信用評等'] === '新客戶(未授信)' || j['信用評等'] === '') {
        isNewCustomer = true;
    }
    if (j['攔截原因'] && String(j['攔截原因']).includes('缺乏歷史交易紀錄')) {
        isNewCustomer = true;
    }
    if (j['客戶ID'] && String(j['客戶ID']).startsWith('CUST99')) {
        isNewCustomer = true;
    }

    if (isNewCustomer) {
        reportData.push({
            json: {
                "客戶編號": j['客戶ID'] || "未知新客戶",
                "KYC開戶狀態": "待全套審查",
                "首筆交易單號": j['訂單ID'] || "無",
                "首筆採購金額(NT$)": j['訂單金額'] || 0,
                "指定對口聯絡人": j['聯絡人'] || '請業務部速向客戶索取',
                "ERP授信建議": "請業務部建立正式 Master Data，並設定初始信用額度"
            }
        });
    }
}

// 🎯 專家級診斷機制：如果經過天羅地網還是 0 筆，直接輸出診斷報告！
if (reportData.length === 0) {
    return [{
        json: {
            "📊_系統診斷結果": "執行失敗！353筆待審單中，100%完全不包含任何新客戶特徵。",
            "🔍_核心病因": "新客戶在前面的 Merge 節點或 Webhook 源頭就已經消失了。",
            "💡_總裁建議排查步驟": "請立刻執行下方的『第二階段』與『第三階段』物理排查。",
            "填補提示_目前收到的前置欄位範例": sampleKeys,
            "第一筆資料盲測": {
                "訂單ID": sampleData ? sampleData['訂單ID'] : "無",
                "客戶ID": sampleData ? sampleData['客戶ID'] : "無",
                "信用評等_現況": sampleData ? sampleData['信用評等'] : "無"
            }
        }
    }];
}

return reportData;

let reportData = [];

for (let item of $input.all()) {
    let j = item.json;

    let arRatio = Number(j['逾期應收帳款比例(%)']) || 0;
    let cashFlow = Number(j['現金流(百萬元)']) || 0;

    // 財務風控條件：現金流為負，或逾期帳款比例 > 12%
    if (cashFlow < 0 || arRatio > 12) {
        reportData.push({
            json: {
                "財報月份": j['月份'],
                "營收表現(百萬元)": j['總營收(百萬元)'],
                "當月現金流(百萬元)": cashFlow,
                "AR逾期比例(%)": arRatio + "%",
                "ERP系統診斷": (cashFlow < 0) ? "🚨 現金流面臨枯竭，建議暫緩採購支出" : "⚠️ 應收帳款逾期嚴重，需立即啟動法務催收(Dunning)程序"
            }
        });
    }
}
return reportData;

let reportData = [];

for (let item of $input.all()) {
    let j = item.json;

    // 只掃描還沒離職的在職員工
    if (String(j['是否離職']).toLowerCase() !== 'true') {
        let overtime = Number(j['加班時數/月']) || 0;
        let salary = Number(j['薪資(新台幣/月)']) || 0;
        let tenure = Number(j['年資']) || 0;

        let riskLevel = "正常";
        let action = "持續觀察";
        let shouldReport = false;

        // 勞基法合規防禦：加班超過 30 小時
        if (overtime >= 30) {
            riskLevel = "🚨 高風險 (過勞/勞基法違規邊緣)";
            action = "HR 需立即強制排休，並調查部門人力配置";
            shouldReport = true;
        } 
        // 離職率防禦：年資大於3年但薪水偏低的高級工程師
        else if (tenure >= 3 && j['職稱'] === '高級工程師' && salary < 45000) {
            riskLevel = "⚠️ 中高風險 (薪資結構倒掛)";
            action = "建議主管啟動留才面談，評估專案調薪";
            shouldReport = true;
        }

        if (shouldReport) {
            reportData.push({
                json: {
                    "員工代號": j['員工ID'],
                    "所屬部門": j['部門'],
                    "職位": j['職稱'],
                    "月加班時數": overtime,
                    "當前薪資(NT$)": salary,
                    "系統風險判定": riskLevel,
                    "HR建議處置": action
                }
            });
        }
    }
}
return reportData;

